  "name": "The High Line",
  "location": "New York City, USA",
  "type": "Green Infrastructure / Urban Regeneration / Waterfront & Rail Re-use",
  "timeline": "1999 (Concept/Friends of the High Line founded) – 2009 (Section 1 opening) to 2019 (Final section completion)",
